import os
import sys
import requests
import hashlib
import time
from datetime import datetime

QUOTE_SECRET = os.getenv('QUOTE_SECRET', '')

def compute_signature(timestamp, url, price):
    data = f"{timestamp}|{url}|{price}".encode('utf-8')
    secret = QUOTE_SECRET.encode('utf-8')
    combined = data + secret
    return hashlib.sha256(combined).hexdigest().lower()

def record(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        data = response.json()
        if 'bitcoin' not in data or 'usd' not in data['bitcoin']:
            print("ERROR", file=sys.stderr)
            sys.exit(1)
        price = data['bitcoin']['usd']
        if not isinstance(price, (int, float)):
            print("ERROR", file=sys.stderr)
            sys.exit(1)

        timestamp = int(time.time())
        formatted_price = f"{price:.0f}" if price.is_integer() else str(price)
        signature = compute_signature(timestamp, url, formatted_price)

        with open('quotes.log', 'a') as f:
            f.write(f"{timestamp}|{url}|{formatted_price}|{signature}\n")
    except requests.RequestException as e:
        print("ERROR", file=sys.stderr)
        sys.exit(1)

def check():
    if not os.path.exists('quotes.log'):
        sys.exit(0)

    with open('quotes.log', 'r') as f:
        lines = f.readlines()

    all_ok = True
    for line in lines:
        stripped_line = line.strip()
        if not stripped_line:
            continue
        parts = stripped_line.split('|')
        if len(parts) != 4:
            print("BAD", file=sys.stderr)
            continue

        timestamp, url, price, stored_signature = parts
        try:
            timestamp_int = int(timestamp)
            price_float = float(price)
        except ValueError:
            print("BAD", file=sys.stderr)
            continue

        computed_signature = compute_signature(timestamp_int, url, price_float)
        if computed_signature == stored_signature:
            print(f"OK {timestamp_int}")
        else:
            print(f"BAD {timestamp_int}")
            all_ok = False

    if all_ok and len(lines) > 0:
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) == 2 and sys.argv[1] == "record":
        if len(sys.argv) != 3:
            print("Usage: python quote_receipt.py record <url>", file=sys.stderr)
            sys.exit(1)
        record(sys.argv[2])
    elif len(sys.argv) == 2 and sys.argv[1] == "check":
        check()
    else:
        print("Usage: python quote_receipt.py record <url> or python quote_receipt.py check", file=sys.stderr)
        sys.exit(1)

