import os
import sys
import json
import hashlib
import time
from urllib.request import urlopen
from urllib.error import HTTPError

QUOTE_SECRET = os.getenv('QUOTE_SECRET', '')

def compute_signature(data: str) -> str:
    secret_bytes = QUOTE_SECRET.encode('utf-8')
    data_bytes = data.encode('utf-8')
    combined = secret_bytes + data_bytes
    return hashlib.sha256(combined).hexdigest().lower()

def record(url: str):
    try:
        with urlopen(url) as response:
            if response.status != 200:
                print('ERROR', file=sys.stderr)
                sys.exit(1)
            data = response.read().decode('utf-8')
            try:
                price = json.loads(data)['bitcoin.usd']
            except (KeyError, json.JSONDecodeError):
                print('ERROR', file=sys.stderr)
                sys.exit(1)
            if not isinstance(price, (int, float)):
                print('ERROR', file=sys.stderr)
                sys.exit(1)
            timestamp = int(time.time())
            price_str = str(price).rstrip('.0') if '.' in str(price) else str(price)
            signature = compute_signature(f"{timestamp}|{url}|{price_str}")
            with open('quotes.log', 'a') as f:
                f.write(f"{timestamp}|{url}|{price_str}|{signature}\n")
    except HTTPError as e:
        print('ERROR', file=sys.stderr)
        sys.exit(1)

def check():
    log_entries = []
    try:
        with open('quotes.log', 'r') as f:
            for line in f:
                line = line.rstrip('\n')
                parts = line.split('|')
                if len(parts) != 4:
                    print('BAD', file=sys.stderr)
                    continue
                timestamp, url, price, stored_sig = parts
                try:
                    price = float(price)
                except ValueError:
                    print('BAD', file=sys.stderr)
                    continue
                computed_sig = compute_signature(f"{timestamp}|{url}|{price}")
                if computed_sig == stored_sig:
                    print(f"OK {timestamp}")
                else:
                    print(f"BAD {timestamp}", file=sys.stderr)
                log_entries.append(True)
    except FileNotFoundError:
        print('BAD', file=sys.stderr)
        sys.exit(1)
    if not log_entries:
        sys.exit(1)
    sys.exit(0)

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print('Usage: python quote_receipt.py record <url> or python quote_receipt.py check', file=sys.stderr)
        sys.exit(1)
    if sys.argv[1] == 'record':
        if len(sys.argv) != 3:
            print('Usage: python quote_receipt.py record <url>', file=sys.stderr)
            sys.exit(1)
        record(sys.argv[2])
    elif sys.argv[1] == 'check':
        check()
    else:
        print('Usage: python quote_receipt.py record <url> or python quote_receipt.py check', file=sys.stderr)
        sys.exit(1)
